    z4_space:'число последовательностей 2^n',z4_all:'все орлы',z4_list:'перебор последовательностей',z4_pascal:'треугольник Паскаля',z4_exact:'ровно k орлов',z4_atleast:'хотя бы k орлов',z4_trap:'независимость бросков',z4_ev:'EV игры с монетами',
