  Object.keys(SN).forEach(function(k){X.skillNames[k]=SN[k];});
  function G(t,k,ex){return{title:SN[t],plain:K[k].plain,steps:K[k].steps,example:ex||K[k].example};}
  ['z1_anchor','z1_frac','z1_swap','z1_build','z1_full','z1_hard','z1_biz'].forEach(function(s){X.skillGuides[s]=G(s,'z1');});
  X.skillGuides.z1_dbl={title:SN.z1_dbl,plain:'Удвоить или разделить пополам число с запятой — это два маленьких действия: целая часть отдельно, хвост после запятой отдельно. Если страшно, думай в деньгах: 7,7 — это 7 $ 70 ¢.',steps:['Раздели: 7,7 = 7 + 0,7.','Удвой каждую: 14 и 1,4.','Сложи: 15,4.','Пополам нечётное: 15,4 = 14 + 1,4 → 7 и 0,7 → 7,7.'],example:{q:'7,7 × 2 и 15,4 ÷ 2',a:['7 × 2 = 14, 0,7 × 2 = 1,4 → 15,4.','15,4 = 14 + 1,4 → 7 + 0,7 = 7,7.']}};
  X.skillGuides.z1_mul={title:SN.z1_mul,plain:'Число с запятой умножай кусками: целая часть и хвост отдельно, потом сложи. Для × 4 проще два раза удвоить, для × 5 — умножить на 10 и взять половину.',steps:['Раздели: 7,7 = 7 + 0,7.','7 × 4 = 28, 0,7 × 4 = 2,8.','Сложи: 30,8.'],example:{q:'0,77 × 2 и 7,7 × 4',a:['0,77 — это 77 центов, × 2 = 154 цента = 1,54.','7,7 → 15,4 → 30,8.']}};
  X.skillGuides.z1_sub={title:SN.z1_sub,plain:'Вычитание с сотыми — по частям: сначала отними целые, потом хвост. Второй путь — убрать запятые (перейти в центы), вычесть целые числа и вернуть запятую.',steps:['30,8 − 1,54: сначала − 1 → 29,8.','Потом − 0,54 → 29,26.','Проверка в центах: 3 080 − 154 = 2 926 → 29,26.'],example:{q:'6,9 − 0,69',a:['6,9 − 0,7 = 6,2.','Отняли на 0,01 больше — вернём: 6,21.']}};
  X.skillGuides.z1_chain={title:SN.z1_chain,plain:'Тяжёлый процент — это три лёгких шага: круглый процент, маленькая поправка, сложить или вычесть. Здесь каждый шаг — отдельная задача, чтобы в голове было только одно число.',steps:['Шаг 1: круглый процент (40% = 4 × 10%).','Шаг 2: поправка (2% = 2 × 1%).','Шаг 3: вычесть или прибавить.','Вслух после каждого шага: «40% — 30,8».'],example:{q:'38% от 77',a:['40%: 7,7 × 4 = 30,8.','2%: 0,77 × 2 = 1,54.','30,8 − 1,54 = 29,26.']}};
  X.skillGuides.z1_est={title:SN.z1_est,plain:'На встрече чаще нужна оценка, а не сотые. Округли процент до десятков и число до удобного, посчитай одно действие и скажи направление: «примерно 29, чуть меньше 30».',steps:['Процент до десятков: 38% → 40%.','Число до 5 или 10: 77 → 75.','40% от 75 = 7,5 × 4 = 30.','Процент округлили вверх → ответ чуть меньше: ≈ 29.'],example:{q:'38% от 77',a:['≈ 40% от 75 = 30.','Точно 29,26 — оценка ошиблась на 2,5%.']}};
  ['z2_coins','z2_tail','z2_split','z2_x4','z2_full','z2_dec','z2_family','z2_biz'].forEach(function(s){X.skillGuides[s]=G(s,'z2');});
  ['z3_anchor','z3_last','z3_pick','z3_exact','z3_approx','z3_biz'].forEach(function(s){X.skillGuides[s]=G(s,'z3');});
  ['z4_space','z4_all','z4_list','z4_pascal','z4_exact','z4_atleast','z4_trap','z4_ev'].forEach(function(s){X.skillGuides[s]=G(s,'z4');});
  ['z5_base','z5_tp','z5_fp','z5_share','z5_full','z5_biz','z5_second','z5_intuit'].forEach(function(s){X.skillGuides[s]=G(s,'z5');});

